changeSet.sql:
alter table kiwi_audit_log add column __TMP_event_details bytea;

update kiwi_audit_log
set __TMP_event_details = lo_get(event_details)
where event_details is not null;

select lo_unlink(event_details)
from kiwi_audit_log
where event_details is not null;

alter table kiwi_audit_log drop column event_details;
alter table kiwi_audit_log rename column __TMP_event_details to event_details;
alter table kiwi_audit_log alter column event_details set not null;

alter table kiwi_audit_log
    change event_details
        event_details longblob not null;
